node -e '
const cases = [
  ["no token set, no header", undefined, {}, 401],
  ["no token set, header sent", undefined, {"x-service-token":"anything"}, 401],
  ["empty token set, no header", "", {}, 401],
  ["token set, correct header", "s3cret", {"x-service-token":"s3cret"}, 200],
  ["token set, wrong header", "s3cret", {"x-service-token":"nope"}, 401],
  ["token set, no header", "s3cret", {}, 401],
  ["token set, cookie session", "s3cret", {cookie:"session=abc"}, 200],
  ["no token set, cookie session", undefined, {cookie:"session=abc"}, 200],
  ["no token set, cookie other", undefined, {cookie:"foo=1"}, 401],
];
let fail = 0;
for (const [name, tok, headers, want] of cases) {
  delete require.cache[require.resolve("./auth")];
  if (tok === undefined) delete process.env.SERVICE_TOKEN; else process.env.SERVICE_TOKEN = tok;
  const { requireLogin } = require("./auth");
  let got = 0;
  const res = { status(c){ got = c; return this; }, json(){ return this; } };
  requireLogin({ headers }, res, () => { got = 200; });
  const ok = got === want;
  if (!ok) fail++;
  console.log((ok ? "PASS" : "FAIL") + "  " + name + "  -> " + got + " (want " + want + ")");
}
process.exit(fail ? 1 : 0);
'
